package runtime

import (
	"crypto/sha256"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// This is the Linux runtime frame from the verified codetools-v0.3.6 release.
// Keep this oracle in both independently shipped decoder packages: neither
// CodeTools nor the shared runtime can stand in for the other's extraction path.
// The fixture is deliberately external (61 MiB), never regenerated by this test.
func TestReleasedRuntimeCompatibility(t *testing.T) {
	fixture := os.Getenv("MINERVA_RELEASED_RUNTIME_ZSTD")
	if fixture == "" {
		t.Skip("set MINERVA_RELEASED_RUNTIME_ZSTD to the official codetools-v0.3.6 Linux runtime frame")
	}
	bundle, err := os.ReadFile(fixture)
	if err != nil {
		t.Fatal(err)
	}
	const releasedSHA = "c76ab9c32484fc73e33c5ac44c6cb7f0616fb7e690c235ade38e5634fc3986ed"
	if got := fmt.Sprintf("%x", sha256.Sum256(bundle)); got != releasedSHA {
		t.Fatalf("wrong official fixture: %s", got)
	}
	req := EnsureRuntimeRequest{EmbeddedBundle: bundle, EmbeddedSHA256: releasedSHA, PluginID: "compatibility", PluginVersion: "0.0.0", DataDir: t.TempDir()}
	root, err := EnsureRuntime(req)
	if err != nil {
		t.Fatal(err)
	}
	// Independently tabulated from the old decoder's released tar inventory:
	// sorted path, type, octal mode, symlink target, and regular-file SHA256.
	const wantTree = "2d03fd045bed2a2e4a77a4a0170a4a40be58c7e8cb85ff3276df392634a83298"
	var rows []string
	err = filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		name, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		// CodeTools alone writes a cache-provenance stamp after extraction.
		if name == "." || name == "source-bundle.sha256" {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		kind, link, checksum := "file", "", ""
		switch {
		case entry.IsDir():
			kind = "dir"
		case info.Mode()&os.ModeSymlink != 0:
			kind = "symlink"
			link, err = os.Readlink(path)
			if err != nil {
				return err
			}
		default:
			file, err := os.Open(path)
			if err != nil {
				return err
			}
			hash := sha256.New()
			_, copyErr := io.Copy(hash, file)
			closeErr := file.Close()
			if copyErr != nil {
				return copyErr
			}
			if closeErr != nil {
				return closeErr
			}
			checksum = fmt.Sprintf("%x", hash.Sum(nil))
		}
		rows = append(rows, fmt.Sprintf("%s\t%s\t%o\t%s\t%s\n", filepath.ToSlash(name), kind, info.Mode().Perm(), link, checksum))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(rows)
	if got := fmt.Sprintf("%x", sha256.Sum256([]byte(strings.Join(rows, "")))); got != wantTree {
		t.Fatalf("released extraction inventory changed: %s", got)
	}
	for name, bad := range map[string][]byte{"truncated": bundle[:len(bundle)/2], "corrupt": append([]byte("bad!"), bundle[4:]...)} {
		t.Run(name, func(t *testing.T) {
			broken := req
			broken.DataDir = t.TempDir()
			broken.EmbeddedBundle = bad
			// Match the supplied checksum so the actual decoder, not the SHA gate, refuses it.
			broken.EmbeddedSHA256 = fmt.Sprintf("%x", sha256.Sum256(bad))
			if _, err := EnsureRuntime(broken); err == nil {
				t.Fatal("damaged stream accepted")
			}
			target := filepath.Join(broken.DataDir, "runtime", broken.PluginVersion)
			if _, err := os.Stat(target); !os.IsNotExist(err) {
				t.Fatalf("accepted cache left behind: %v", err)
			}
			entries, err := os.ReadDir(filepath.Dir(target))
			if err != nil {
				t.Fatal(err)
			}
			for _, entry := range entries {
				if strings.HasPrefix(entry.Name(), ".tmp-extract-") {
					t.Fatal("partial extraction left behind")
				}
			}
		})
	}
}
